#!/bin/bash
# usage: start_mock.sh <MODE> <tag> ; refuses to start if anything listens on :8042; writes $V/<tag>-mock.pid with the exact python PID
set -u
if ss -ltnp | grep -E '(127\.0\.0\.1|0\.0\.0\.0|\*|\[::\]):8042\s'; then echo "PORT 8042 BUSY - not starting"; exit 3; fi
MODE=$1 PAYLOAD=/tmp/claude-1000/-home-nomad-ai-projects-repositories-solar-system-realistic-sim/3e06ef45-898e-459a-9e2c-307d6a081174/scratchpad/h1/upstream/physics_payload.json PNG=/tmp/claude-1000/-home-nomad-ai-projects-repositories-solar-system-realistic-sim/3e06ef45-898e-459a-9e2c-307d6a081174/scratchpad/h1/upstream/aia_304_tile_192408248.png LOG=/tmp/claude-1000/-home-nomad-ai-projects-repositories-solar-system-realistic-sim/3e06ef45-898e-459a-9e2c-307d6a081174/scratchpad/h1/verify/browser/$2-mock-requests.jsonl   nohup bash -c 'echo $$ > /tmp/claude-1000/-home-nomad-ai-projects-repositories-solar-system-realistic-sim/3e06ef45-898e-459a-9e2c-307d6a081174/scratchpad/h1/verify/browser/'"$2"'-mock.pid; exec /tmp/claude-1000/-home-nomad-ai-projects-repositories-solar-system-realistic-sim/3e06ef45-898e-459a-9e2c-307d6a081174/scratchpad/venv/bin/python /tmp/claude-1000/-home-nomad-ai-projects-repositories-solar-system-realistic-sim/3e06ef45-898e-459a-9e2c-307d6a081174/scratchpad/h1/verify/browser/mock_backend.py' > /tmp/claude-1000/-home-nomad-ai-projects-repositories-solar-system-realistic-sim/3e06ef45-898e-459a-9e2c-307d6a081174/scratchpad/h1/verify/browser/$2-mock.log 2>&1 &
for i in $(seq 1 20); do curl -s -m 1 -o /dev/null http://127.0.0.1:8042/health && break; sleep 0.3; done
P=$(cat /tmp/claude-1000/-home-nomad-ai-projects-repositories-solar-system-realistic-sim/3e06ef45-898e-459a-9e2c-307d6a081174/scratchpad/h1/verify/browser/$2-mock.pid); echo "mock $1 pid $P"; ss -ltnp | grep -E '(127\.0\.0\.1|0\.0\.0\.0|\*|\[::\]):8042\s'; cat /tmp/claude-1000/-home-nomad-ai-projects-repositories-solar-system-realistic-sim/3e06ef45-898e-459a-9e2c-307d6a081174/scratchpad/h1/verify/browser/$2-mock.log
